mod solution;

fn valid(_input: &str, actual: &str, expected: &str) -> bool { actual == expected }

fn main() {
    let cases = [
        ("[2,1,2,4,3]","4,2,4,-1,-1"),
        ("[1,3,2]","3,-1,-1"),
        ("[1,2,3,4,5,6,7]","2,3,4,5,6,7,-1"),
        ("[3,3,3,3,3,3,3]","-1,-1,-1,-1,-1,-1,-1"),
        ("[8,7,6,5,4,3,2]","-1,-1,-1,-1,-1,-1,-1"),
        ("  \n[2,1,2,4,3]\n  ","4,2,4,-1,-1"),
        ("\n[8,7,6,5,4,3,2]\n","-1,-1,-1,-1,-1,-1,-1")
    ];
    for (i,(input,expected)) in cases.iter().enumerate() {
        let actual = solution::solve(input);
        if !valid(input,&actual,expected) { eprintln!("PRIVATE CASE {} FAILED",i+1); std::process::exit(1); }
    }
    println!("PASS next-greater-stack");
}
